/**
 * @summary Filing status and key totals for the six periods of a year
 */
export const ListTaxFilingsQueryParams = zod.object({
  year: zod.coerce.number().int(),
});

export const ListTaxFilingsResponseItem = zod.object({
  period: zod.string(),
  status: zod.enum(["未申報", "已申報"]),
  sales_total: zod.number().int(),
  output_tax: zod.number().int(),
  input_tax: zod.number().int(),
  payable: zod.number().int(),
  carry_out: zod.number().int(),
  invoice_count: zod.number().int(),
  deadline: zod.string(),
});
export const ListTaxFilingsResponse = zod.array(ListTaxFilingsResponseItem);

/**
 * @summary Mark a period filed / reopen it, or set the carried-in credit
 */
export const UpdateTaxFilingParams = zod.object({
  period: zod.coerce.string(),
});

export const UpdateTaxFilingBody = zod.object({
  status: zod.enum(["未申報", "已申報"]).optional(),
  carry_in_override: zod.number().int().nullish(),
  note: zod.string().nullish(),
});

export const UpdateTaxFilingResponse = zod.object({
  period: zod.string(),
  status: zod.enum(["未申報", "已申報"]),
  filed_at: zod.coerce.date().nullish(),
  carry_in_override: zod.number().int().nullish(),
  note: zod.string().nullish(),
});
